def round_cents(value: str) -> Decimal:
    return Decimal(value).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)


def split(total_cents: int, parts: int) -> list[int]:
    share = total_cents // parts
    return [share] * parts
